-- ============================================================
-- SCRIPT DE BANCO DE DADOS - PROJETO CHRONOHISTORY (Supabase / PostgreSQL)
-- ============================================================

-- Recria as tabelas para eliminar colunas antigas com tipos incompatíveis (ex: erro 22P02 quando ano era inteiro)
DROP TABLE IF EXISTS public.evento CASCADE;
DROP TABLE IF EXISTS public.usuario CASCADE;
DROP TABLE IF EXISTS public.imagens CASCADE;

-- 1. TABELA DE USUÁRIOS
CREATE TABLE public.usuario (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "user" VARCHAR(100) UNIQUE NOT NULL,
    senha VARCHAR(255) NOT NULL,
    nome VARCHAR(150) NOT NULL,
    perfil VARCHAR(50) DEFAULT 'aluno',
    fase_jogo INT DEFAULT 1,
    created_at TIMESTAMPTZ DEFAULT NOW()
);
CREATE INDEX idx_usuario_user ON public.usuario("user");

-- 2. TABELA DE EVENTOS HISTÓRICOS (ano_inicio como TEXT para aceitar textos como 'c. 1.5 milhões a.C.')
CREATE TABLE public.evento (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    nome TEXT NOT NULL,
    periodo TEXT,
    ano_inicio TEXT,
    ano_termino TEXT,
    lugar TEXT,
    acontecimento TEXT,
    figuras_historicas JSONB DEFAULT '[]'::jsonb,
    created_at TIMESTAMPTZ DEFAULT NOW()
);
CREATE INDEX idx_evento_periodo ON public.evento(periodo);

-- 3. TABELA DE IMAGENS / OBRAS DA GALERIA
CREATE TABLE public.imagens (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    titulo TEXT NOT NULL,
    pintor TEXT,
    periodo TEXT,
    ano TEXT,
    contexto TEXT,
    url TEXT NOT NULL,
    created_at TIMESTAMPTZ DEFAULT NOW()
);

-- ============================================================
-- DADOS INICIAIS (SEED / MOCK DATA)
-- ============================================================

-- Inserir usuários iniciais para teste
ON CONFLICT DO NOTHING;

-- Inserir TODOS os 100 eventos do periodos.json na tabela public.evento

-- ============================================================
-- POLÍTICAS DE SEGURANÇA (Row Level Security - RLS)
-- ============================================================
ALTER TABLE public.usuario ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.evento ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.imagens ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "Permitir tudo na tabela usuario" ON public.usuario;
CREATE POLICY "Permitir tudo na tabela usuario" ON public.usuario FOR ALL USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Permitir tudo na tabela evento" ON public.evento;
CREATE POLICY "Permitir tudo na tabela evento" ON public.evento FOR ALL USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "Permitir tudo na tabela imagens" ON public.imagens;
CREATE POLICY "Permitir tudo na tabela imagens" ON public.imagens FOR ALL USING (true) WITH CHECK (true);